const redeemPublisherEnrollment = `-- name: RedeemPublisherEnrollment :execrows
UPDATE control.publisher_enrollment_keys
SET redeemed_identity_id = $1,
    redeemed_key_id = $2, redeemed_grant_id = $3,
    redeemed_public_key = $4, redeemed_at = $5
WHERE id = $6 AND redeemed_at IS NULL
`

type RedeemPublisherEnrollmentParams struct {
	PublisherIdentityID pgtype.Text
	KeyID               pgtype.Text
	GrantID             pgtype.Text
	PublicKey           []byte
	RedeemedAt          pgtype.Timestamptz
	ID                  string
}

func (q *Queries) RedeemPublisherEnrollment(ctx context.Context, arg RedeemPublisherEnrollmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, redeemPublisherEnrollment,
		arg.PublisherIdentityID,
		arg.KeyID,
		arg.GrantID,
		arg.PublicKey,
		arg.RedeemedAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

