const revokePublisherIdentityGrant = `-- name: RevokePublisherIdentityGrant :execrows
UPDATE control.publisher_identity_grants AS grants SET revoked_at = COALESCE(grants.revoked_at, $1)
WHERE grants.id = $2 AND grants.publisher_identity_id = $3
    AND EXISTS (SELECT 1 FROM control.publisher_identities AS identities
        WHERE identities.id = $3 AND identities.team_id = $4)
`

type RevokePublisherIdentityGrantParams struct {
	RevokedAt           pgtype.Timestamptz
	ID                  string
	PublisherIdentityID string
	TeamID              string
}

